-- dml/04_universities.sql — 대학교(캠퍼스 = 한 점) · 생성 파일, 손으로 고치지 않는다
--
-- 만든 곳: dml/tools/gen_universities.py — 규칙(폐교 · 원격 제외, 대학원 1km 합치기, 별도 캠퍼스 점)은 그 머리말에 있다.
-- 원천: data.go.kr 15138981 「교육부_대학교 주소기반 좌표정보」 · 이용허락범위 제한 없음
--       파일 교육부_대학교 주소기반 좌표정보_20251126.xlsx · sha256 b1c9a4257218392e4ed9c10ea599ee67319f2102fc5f6cd4445b68d7eaa8e1d5
-- 행 수: 493 = 학교 캠퍼스 452(대학 235 · 전문대학 173 · 대학원대학 44)
--        + 대학원만 있는 별도 캠퍼스 41 + 모체 없는 대학원 0 · 시군구가 붙은 행 493
-- 시군구를 못 정한 행: 없음
-- 뺀 것: 원천 2142행 중 폐교 499 · 실재 학교 아님 1 · 원격 대학 23(그 대학원 17) ·
--        캠퍼스 점에 합친 대학원 1066
--
-- ⚠ universities 테이블을 만드는 V 마이그레이션이 먼저(또는 같은 커밋) 나가야 한다 — 없으면 ERROR 1146 으로 CD 의 dml 단계가 멈춘다.
-- 멱등: 학교코드(code) upsert. 원천에서 사라진 학교는 지우지 않고 is_active = 0.
-- 실행: mysql --default-character-set=utf8mb4 <DB> < dml/04_universities.sql
-- =============================================================================

ON DUPLICATE KEY UPDATE name_ko        = VALUES(name_ko),
                        name_en        = VALUES(name_en),
                        campus_name_ko = VALUES(campus_name_ko),
                        campus_name_en = VALUES(campus_name_en),
                        address_road   = VALUES(address_road),
                        lat            = VALUES(lat),
                        lng            = VALUES(lng),
                        region_id      = VALUES(region_id),
                        is_active      = VALUES(is_active);

UPDATE universities
SET is_active = 0
WHERE is_active = 1
